def parse_font_text(text,font_path,prog_base,font_arg):
    lines=text.splitlines()
    if not lines:
        sys.stderr.write(f"{prog_base}: {font_arg}: Not a FIGlet 2 font file\n")
        sys.exit(1)
    header=lines[0]
    if not (header.startswith("flf2") or header.startswith("tlf2")):
        sys.stderr.write(f"{prog_base}: {font_arg}: Not a FIGlet 2 font file\n")
