        nxt=raw[cur] if cur<len(raw) else ""
        if not is_tag_line(nxt):
            if cur+7*height <= len(raw):
                after_german=raw[cur+7*height] if cur+7*height < len(raw) else ""
                if is_tag_line(after_german) or codetag_count==0:
                    for gc in german_codes:
                        if cur+height>len(raw):
                            break
                        glyph=[]
                        for r in range(height):
                            line=raw[cur] if cur<len(raw) else ""
                            cur+=1
                            is_last=(r==height-1)
                            glyph.append(strip_line(line,is_last))
                        glyphs[gc]=glyph
    for _ in range(codetag_count):
        if cur>=len(raw):
            break
        tag_line=raw[cur].strip()
        cur+=1
        if not tag_line:
            continue
        first_token=tag_line.split()[0]
        try:
            if first_token.startswith("0x") or first_token.startswith("0X"):
