def decode_token(tok):
    if not tok:
        return None
    if tok.startswith("\\0x") or tok.startswith("\\0X"):
        hexpart=tok[3:]
        if hexpart=="":
            return None
        try:
            return int(hexpart,16)
        except:
            return None
    if tok.startswith("\\-"):
        try:
            return int(tok[1:])
        except:
            return None
    if tok.startswith("\\"):
        octpart=tok[1:]
        if octpart.isdigit() and set(octpart) <= set("01234567"):
            try:
                return int(octpart,8)
            except:
                pass
        return None
    if len(tok)==1:
        return ord(tok)
    return None

def parse_control_file(path):
    mappings={}
    flags=set()
    try:
        with open(path,'r',encoding='utf-8',errors='ignore') as f:
            for raw_line in f:
                line=raw_line.strip()
                if not line or line.startswith("#"):
                    continue
                if line.startswith("&"):
                    continue
                if line == "u":
                    flags.add("u"); continue
                if line == "h":
                    flags.add("h"); continue
                if line.startswith("flc2"):
                    continue
                m=re.match(r'^\s*(0x[0-9a-fA-F]+)\s+(0x[0-9a-fA-F]+)',line)
                if m:
                    src_hex=m.group(1); dst_hex=m.group(2)
                    try:
                        src=int(src_hex,16); dst=int(dst_hex,16)
                        mappings[src]=dst
                    except:
                        pass
                    continue
                if line.startswith("t "):
                    rest=line[2:].strip()
                    parts=rest.split()
                    if len(parts)>=2:
                        src_tok=parts[0]; dst_tok=parts[1]
                        if '-' in src_tok and not src_tok.startswith("\\"):
                            src_range=re.match(r'(\S+)-(\S+)',src_tok)
                            dst_range=re.match(r'(\S+)-(\S+)',dst_tok)
                            if src_range and dst_range:
                                src_start_s,src_end_s=src_range.groups()
                                dst_start_s,dst_end_s=dst_range.groups()
                                src_start=decode_token(src_start_s)
                                src_end=decode_token(src_end_s)
                                dst_start=decode_token(dst_start_s)
                                dst_end=decode_token(dst_end_s)
                                if src_start is not None and src_end is not None and dst_start is not None:
                                    s=src_start; d=dst_start
                                    while s <= src_end and d <= dst_end:
                                        mappings[s]=d
                                        s+=1; d+=1
                            continue
                        src_code=decode_token(src_tok)
                        dst_code=decode_token(dst_tok)
                        if src_code is not None and dst_code is not None:
                            mappings[src_code]=dst_code
                    continue
                if line.startswith("g ") or line.startswith("f "):
                    continue
    except:
        pass
    return mappings,flags

