            search_dirs.append(fontdir)
        search_dirs.append(".")
        for d in search_dirs:
            if has_ext:
                cand=os.path.join(d,name)
                r=try_path(cand)
                if r:
                    return r
            else:
                for ext in extensions:
                    cand=os.path.join(d,name+ext)
                    r=try_path(cand)
                    if r:
                        return r
        return None

def load_font(font_path, prog_base, font_arg):
    if not font_path or not os.path.isfile(font_path):
        sys.stderr.write(f"{prog_base}: {font_arg}: Unable to open font file\n")
        sys.exit(1)
    try:
        with open(font_path,'rb') as f:
            magic=f.read(4)
            if magic.startswith(b'PK\x03\x04'):
                f.seek(0)
                try:
                    z=zipfile.ZipFile(f)
                    nl=z.namelist()
                    if nl:
                        data=z.read(nl[0])
                        text=data.decode('utf-8',errors='ignore')
                        return parse_font_text(text,font_path,prog_base,font_arg)
                except:
                    pass
    except:
        pass
    try:
        with open(font_path,'r',encoding='utf-8',errors='ignore') as f:
            text=f.read()
        return parse_font_text(text,font_path,prog_base,font_arg)
    except SystemExit:
        raise
    except:
        sys.stderr.write(f"{prog_base}: {font_arg}: Unable to open font file\n")
        sys.exit(1)

def parse_font_text(text,font_path,prog_base,font_arg):
    lines=text.splitlines()
    if not lines:
        sys.stderr.write(f"{prog_base}: {font_arg}: Not a FIGlet 2 font file\n")
        sys.exit(1)
    header=lines[0]
    if not (header.startswith("flf2") or header.startswith("tlf2")):
        sys.stderr.write(f"{prog_base}: {font_arg}: Not a FIGlet 2 font file\n")
        sys.exit(1)
    if len(header)<6:
        sys.stderr.write(f"{prog_base}: {font_arg}: Not a FIGlet 2 font file\n")
        sys.exit(1)
    hardblank=header[5]
    rest=header[6:].strip()
    parts=rest.split()
    try:
        height=int(parts[0]); baseline=int(parts[1]) if len(parts)>1 else 0
        maxlen=int(parts[2]) if len(parts)>2 else 0
        old_layout=int(parts[3]) if len(parts)>3 else 0
        comment_lines=int(parts[4]) if len(parts)>4 else 0
        print_direction=int(parts[5]) if len(parts)>5 else 0
        full_layout=int(parts[6]) if len(parts)>6 else 0
        codetag_count=int(parts[7]) if len(parts)>7 else 0
    except:
        sys.stderr.write(f"{prog_base}: {font_arg}: Not a FIGlet 2 font file\n")
        sys.exit(1)
    if height<=0:
        sys.stderr.write(f"{prog_base}: {font_arg}: Not a FIGlet 2 font file\n")
        sys.exit(1)
    idx=1
    if idx+comment_lines>len(lines):
        comment_lines=len(lines)-idx
    idx+=comment_lines
    raw=lines[idx:]
    glyphs={}
    def strip_line(line,is_last):
        if is_last:
            if len(line)>=2 and line.endswith("@@"):
                return line[:-2]
            elif len(line)>=2 and line[-1]==line[-2]:
                return line[:-2]
            else:
                return line[:-1] if len(line)>=1 else line
        else:
            return line[:-1] if len(line)>=1 else line
    cur=0
    needed=95*height
    if len(raw)<needed:
        sys.stderr.write(f"{prog_base}: {font_arg}: Not a FIGlet 2 font file\n")
        sys.exit(1)
    for code in range(32,127):
        glyph=[]
        for r in range(height):
            line=raw[cur] if cur<len(raw) else ""
            cur+=1
            is_last=(r==height-1)
            glyph.append(strip_line(line,is_last))
        glyphs[code]=glyph
    german_codes=[196,214,220,228,246,252,223]
    def is_tag_line(line):
        s=line.strip()
        if not s:
            return False
        if line.endswith("@"):
            return False
        first=s.split()[0] if s else ""
        is_num=False
        if first.startswith("0x") or first.startswith("0X"):
            try:
                int(first,16); is_num=True
            except:
                pass
        elif first.lstrip("-+").isdigit():
            try:
                int(first); is_num=True
            except:
                pass
        if is_num:
            return True
        return False
    if cur < len(raw):
        nxt=raw[cur] if cur<len(raw) else ""
        if not is_tag_line(nxt):
            if cur+7*height <= len(raw):
                after_german=raw[cur+7*height] if cur+7*height < len(raw) else ""
                if is_tag_line(after_german) or codetag_count==0:
                    for gc in german_codes:
                        if cur+height>len(raw):
                            break
                        glyph=[]
                        for r in range(height):
                            line=raw[cur] if cur<len(raw) else ""
                            cur+=1
                            is_last=(r==height-1)
                            glyph.append(strip_line(line,is_last))
                        glyphs[gc]=glyph
    for _ in range(codetag_count):
        if cur>=len(raw):
            break
        tag_line=raw[cur].strip()
        cur+=1
        if not tag_line:
            continue
        first_token=tag_line.split()[0]
        try:
            if first_token.startswith("0x") or first_token.startswith("0X"):
                code=int(first_token,16)
            else:
                code=int(first_token)
        except:
            continue
        glyph=[]
        for r in range(height):
            if cur>=len(raw):
                break
            line=raw[cur]
            cur+=1
            is_last=(r==height-1)
            glyph.append(strip_line(line,is_last))
        glyphs[code]=glyph
    return {'hardblank':hardblank,'height':height,'baseline':baseline,'maxlen':maxlen,'old_layout':old_layout,'print_direction':print_direction,'full_layout':full_layout,'codetag_count':codetag_count,'glyphs':glyphs,'font_path':font_path}

def load_control_file(fontdir, ctrl_name, prog_base):
    path=find_file(fontdir, ctrl_name, [".flc"])
    if not path:
        sys.stderr.write(f"{prog_base}: {ctrl_name}: Unable to open control file\n")
        sys.exit(1)
    try:
        with open(path,'r',encoding='utf-8',errors='ignore') as f:
            content=f.read()
            lines=content.splitlines()
            has_valid=False
            for line in lines:
                ls=line.strip()
                if not ls or ls.startswith("#") or ls.startswith("&"):
                    continue
                if ls.startswith("flc2"):
                    has_valid=True; break
                if ls=="u" or ls=="h" or ls.startswith("t ") or ls.startswith("g ") or ls.startswith("f "):
                    has_valid=True; break
                if re.match(r'^\s*0x[0-9a-fA-F]+\s+0x[0-9a-fA-F]+',line):
                    has_valid=True; break
                if re.match(r'^\s*0x[0-9a-fA-F]+',line):
                    toks=line.split()
                    if len(toks)>=2 and toks[0].lower().startswith("0x") and toks[1].lower().startswith("0x"):
                        has_valid=True; break
            if not has_valid and not content.strip().startswith("flc2"):
                if "0x" not in content:
                    sys.stderr.write(f"{prog_base}: {ctrl_name}: Not a FIGlet 2 control file\n")
                    sys.exit(1)
                if not re.search(r'0x[0-9a-fA-F]+\s+0x[0-9a-fA-F]+',content):
                    sys.stderr.write(f"{prog_base}: {ctrl_name}: Not a FIGlet 2 control file\n")
                    sys.exit(1)
    except SystemExit:
        raise
    except Exception as e:
        sys.stderr.write(f"{prog_base}: {ctrl_name}: Unable to open control file\n")
        sys.exit(1)
    return path

def decode_token(tok):
    if not tok:
        return None
    if tok.startswith("\\0x") or tok.startswith("\\0X"):
        hexpart=tok[3:]
        if hexpart=="":
            return None
        try:
            return int(hexpart,16)
        except:
            return None
    if tok.startswith("\\-"):
        try:
            return int(tok[1:])
        except:
            return None
    if tok.startswith("\\"):
        octpart=tok[1:]
        if octpart.isdigit() and set(octpart) <= set("01234567"):
            try:
                return int(octpart,8)
            except:
                pass
        return None
    if len(tok)==1:
        return ord(tok)
    return None

def parse_control_file(path):
    mappings={}
    flags=set()
    try:
        with open(path,'r',encoding='utf-8',errors='ignore') as f:
            for raw_line in f:
                line=raw_line.strip()
                if not line or line.startswith("#"):
                    continue
                if line.startswith("&"):
                    continue
                if line == "u":
                    flags.add("u"); continue
                if line == "h":
                    flags.add("h"); continue
                if line.startswith("flc2"):
                    continue
                m=re.match(r'^\s*(0x[0-9a-fA-F]+)\s+(0x[0-9a-fA-F]+)',line)
                if m:
                    src_hex=m.group(1); dst_hex=m.group(2)
                    try:
                        src=int(src_hex,16); dst=int(dst_hex,16)
                        mappings[src]=dst
                    except:
                        pass
                    continue
                if line.startswith("t "):
                    rest=line[2:].strip()
                    parts=rest.split()
                    if len(parts)>=2:
                        src_tok=parts[0]; dst_tok=parts[1]
                        if '-' in src_tok and not src_tok.startswith("\\"):
                            src_range=re.match(r'(\S+)-(\S+)',src_tok)
                            dst_range=re.match(r'(\S+)-(\S+)',dst_tok)
                            if src_range and dst_range:
                                src_start_s,src_end_s=src_range.groups()
                                dst_start_s,dst_end_s=dst_range.groups()
                                src_start=decode_token(src_start_s)
                                src_end=decode_token(src_end_s)
                                dst_start=decode_token(dst_start_s)
                                dst_end=decode_token(dst_end_s)
                                if src_start is not None and src_end is not None and dst_start is not None:
                                    s=src_start; d=dst_start
                                    while s <= src_end and d <= dst_end:
                                        mappings[s]=d
                                        s+=1; d+=1
                            continue
                        src_code=decode_token(src_tok)
                        dst_code=decode_token(dst_tok)
                        if src_code is not None and dst_code is not None:
                            mappings[src_code]=dst_code
                    continue
                if line.startswith("g ") or line.startswith("f "):
                    continue
    except:
        pass
    return mappings,flags

def get_font_default_mode(font):
    if font['old_layout']==-1:
        return 'full'
    if font['full_layout'] & 128:
        return 'smush'
    if font['full_layout'] & 64:
        return 'kern'
    return 'kern'

def can_smush(a,b,hardblank):
    if a==' ' or b==' ':
        return True
    if a==hardblank or b==hardblank:
        return True
    if a==b:
        return True
    hierarchy=set("|/\\[]{}()<>")
    if a=="_" and b in hierarchy:
        return True
    if b=="_" and a in hierarchy:
        return True
    if a in hierarchy and b in hierarchy:
        return True
    return False

def smush_chars(a,b,hardblank):
    if a==' ':
        return b
    if b==' ':
        return a
    if a==hardblank and b==hardblank:
        return hardblank
    if a==hardblank:
        return b
    if b==hardblank:
        return a
    if a==b:
        return a
    hierarchy="|/\\[]{}()<>"
    if a=="_" and b in hierarchy:
        return b
    if b=="_" and a in hierarchy:
        return a
    if a in hierarchy and b in hierarchy:
        return b
    return b

def compute_overlap(glyph_a, glyph_b, mode, font):
    h=len(glyph_a)
    hardblank=font['hardblank']
    if mode=='full':
        return 0
    max_width_a=max(len(r) for r in glyph_a) if glyph_a else 0
    max_width_b=max(len(r) for r in glyph_b) if glyph_b else 0
    max_try=min(max_width_a, max_width_b)
    eff_mode=mode
    if mode=='font_default':
        eff_mode=get_font_default_mode(font)
    best=0
    for k in range(max_try, -1, -1):
        feasible=True
        for i in range(h):
            a_row=glyph_a[i] if i<len(glyph_a) else ""
            b_row=glyph_b[i] if i<len(glyph_b) else ""
            for j in range(k):
                a_idx=len(a_row)-k+j
                if 0 <= a_idx < len(a_row):
                    ca=a_row[a_idx]
                else:
                    ca=' '
                b_idx=j
                if 0 <= b_idx < len(b_row):
                    cb=b_row[b_idx]
                else:
                    cb=' '
                if eff_mode=='kern':
                    is_blank_a=(ca==' ' or ca==hardblank)
                    is_blank_b=(cb==' ' or cb==hardblank)
                    if not is_blank_a and not is_blank_b:
                        feasible=False
                        break
                elif eff_mode=='smush':
                    is_blank_a=(ca==' ' or ca==hardblank)
                    is_blank_b=(cb==' ' or cb==hardblank)
                    if not is_blank_a and not is_blank_b:
                        if not can_smush(ca,cb,hardblank):
                            feasible=False
                            break
                elif eff_mode=='overlap':
                    pass
                else:
                    feasible=False
                    break
            if not feasible:
                break
        if feasible:
            best=k
            break
    return best

def merge_glyphs(cur_block, glyph_b, mode, font):
    h=font['height']
    hardblank=font['hardblank']
    if not cur_block:
        return glyph_b[:]
    overlap=compute_overlap(cur_block, glyph_b, mode, font)
    eff_mode=mode
    if mode=='font_default':
        eff_mode=get_font_default_mode(font)
    new_block=[]
    for i in range(h):
        a_row=cur_block[i] if i<len(cur_block) else ""
        b_row=glyph_b[i] if i<len(glyph_b) else ""
        if overlap==0:
            new_row=a_row + b_row
        else:
            offset=len(a_row)-overlap
            if offset<0:
                ov=""
                for j in range(overlap):
                    a_idx= len(a_row)-overlap + j
                    if 0 <= a_idx < len(a_row):
                        ca=a_row[a_idx]
                    else:
                        ca=' '
                    b_idx=j
                    if 0 <= b_idx < len(b_row):
                        cb=b_row[b_idx]
                    else:
                        cb=' '
                    if ca==' ' or ca==hardblank:
                        ov+=cb
                    elif cb==' ' or cb==hardblank:
                        ov+=ca
                    else:
                        if eff_mode=='smush':
                            ov+=smush_chars(ca,cb,hardblank)
                        elif eff_mode=='kern':
                            ov+=cb
                        elif eff_mode=='overlap':
                            ov+=smush_chars(ca,cb,hardblank)
                        else:
                            ov+=cb
                right=b_row[overlap:]
                new_row=ov + right
            else:
                left=a_row[:offset]
                ov=""
                for j in range(overlap):
                    ca=a_row[offset+j] if offset+j < len(a_row) else ' '
                    cb=b_row[j] if j < len(b_row) else ' '
                    if ca==' ' or ca==hardblank:
                        ov+=cb
                    elif cb==' ' or cb==hardblank:
                        ov+=ca
                    else:
                        if eff_mode=='smush':
                            ov+=smush_chars(ca,cb,hardblank)
                        elif eff_mode=='kern':
                            ov+=cb
                        elif eff_mode=='overlap':
                            ov+=smush_chars(ca,cb,hardblank)
                        else:
                            ov+=cb
                right=b_row[overlap:] if overlap < len(b_row) else ""
                new_row=left+ov+right
        new_block.append(new_row)
    return new_block

def get_glyph(font, code):
    glyphs=font['glyphs']
    if code in glyphs:
        return glyphs[code]
    if 63 in glyphs:
        return glyphs[63]
    h=font['height']
    if 32 in glyphs:
        w=len(glyphs[32][0]) if glyphs[32] else 1
        return [" "*w for _ in range(h)]
    return [" " for _ in range(h)]

def render_string(s, font, mode):
    h=font['height']
    if not s:
        return [""]*h
    block=None
    for ch in s:
        code=ord(ch)
        glyph=get_glyph(font, code)
        if block is None:
            block=glyph[:]
        else:
            block=merge_glyphs(block, glyph, mode, font)
    hb=font['hardblank']
    new_block=[]
    for row in block:
        new_row=row.replace(hb, ' ')
        new_block.append(new_row)
    return new_block

def render_text(text, font, mode, width, justify, direction):
    eff_dir = font['print_direction'] if direction is None else direction
    logical_lines = text.split('\n')
    out_lines = []
    if width == 1:
        for log_line in logical_lines:
            if log_line == "":
                for _ in range(font['height']):
                    out_lines.append("")
                continue
            line_to_render = log_line[::-1] if eff_dir==1 else log_line
            for ch in line_to_render:
                if ch == ' ':
                    continue
                block = render_string(ch, font, mode)
                for row in block:
                    out_lines.append(row)
        return out_lines
    for log_line in logical_lines:
        if log_line == "":
            for _ in range(font['height']):
                out_lines.append("")
            continue
        if eff_dir==1:
            log_line = log_line[::-1]
        if log_line.strip() == "":
            block = render_string(log_line, font, mode)
            line_width = max(len(r) for r in block) if block else 0
            pad=0
            if justify=='c':
                pad = (width - line_width)//2
                if pad<0: pad=0
            elif justify=='r':
                pad = width - line_width
                if pad<0: pad=0
            elif justify=='x':
                if eff_dir==1:
                    pad= width - line_width
                    if pad<0: pad=0
                else:
                    pad=0
            for row in block:
                out_lines.append(" "*pad + row)
            continue
        words = log_line.split(' ')
        current_line_str = ""
        for wi, word in enumerate(words):
            if current_line_str == "":
                candidate = word
            else:
                candidate = current_line_str + " " + word
            cand_block = render_string(candidate, font, mode)
            cand_width = max(len(r) for r in cand_block) if cand_block else 0
            if cand_width > width and current_line_str != "":
                block = render_string(current_line_str, font, mode)
                line_width = max(len(r) for r in block) if block else 0
                pad=0
                if justify=='c':
                    pad = (width - line_width)//2
                    if pad<0: pad=0
                elif justify=='r':
                    pad = width - line_width
                    if pad<0: pad=0
                elif justify=='x':
                    if eff_dir==1:
                        pad = width - line_width
                        if pad<0: pad=0
                    else:
                        pad=0
                for row in block:
                    out_lines.append(" "*pad + row)
                current_line_str = word
            else:
                current_line_str = candidate
        if current_line_str != "" or len(words)==0:
            if current_line_str == "" and log_line != "":
                pass
            else:
                block = render_string(current_line_str, font, mode)
                line_width = max(len(r) for r in block) if block else 0
                pad=0
                if justify=='c':
                    pad = (width - line_width)//2
                    if pad<0: pad=0
                elif justify=='r':
                    pad = width - line_width
                    if pad<0: pad=0
                elif justify=='x':
                    if eff_dir==1:
                        pad = width - line_width
                        if pad<0: pad=0
                    else:
                        pad=0
                for row in block:
                    out_lines.append(" "*pad + row)
    return out_lines

